phase1.code:
use std::sync::{Arc, Mutex};
use std::thread;

fn main() {
    // ---- Sample text ----
    let text = vec![
        "Hello world from Rust",
        "Rust is a systems programming language",
        "Hello from the other side",
        "World of Rustaceans",
        "Hello world!",
    ];

    // ---- Count words sequentially ----
    let sequential_count = count_words_sequential(&text);
    println!("Sequential count: {}", sequential_count);

    // ---- Count words with threads ----
    let thread_count = count_words_threaded(&text);
    println!("Thread count: {}", thread_count);

    // ---- Count word frequencies with threads ----
    let frequencies = count_word_frequencies(&text);
    println!("\nWord frequencies:");
    for (word, count) in frequencies {
        if count > 1 {
            println!("  {}: {}", word, count);
        }
    }
}

fn count_words_sequential(text: &[&str]) -> usize {
    text.iter().map(|line| line.split_whitespace().count()).sum()
}

fn count_words_threaded(text: &[&str]) -> usize {
    let counter = Arc::new(Mutex::new(0));
    let mut handles = vec![];

    for line in text {
        let counter = Arc::clone(&counter);
        let line = line.to_string();

        let handle = thread::spawn(move || {
            let count = line.split_whitespace().count();
            let mut total = counter.lock().unwrap();
            *total += count;
        });
        handles.push(handle);
    }

    for handle in handles {
        handle.join().unwrap();
    }

    *counter.lock().unwrap()
}

fn count_word_frequencies(text: &[&str]) -> Vec<(String, usize)> {
    use std::collections::HashMap;

    let frequencies = Arc::new(Mutex::new(HashMap::new()));
    let mut handles = vec![];

    for line in text {
        let frequencies = Arc::clone(&frequencies);
        let line = line.to_string();

        let handle = thread::spawn(move || {
            let mut local_map = HashMap::new();

            for word in line.split_whitespace() {
                let word = word.to_lowercase();
                *local_map.entry(word).or_insert(0) += 1;
            }

            // Merge local map into global
            let mut global = frequencies.lock().unwrap();
            for (word, count) in local_map {
                *global.entry(word).or_insert(0) += count;
            }
        });
        handles.push(handle);
    }

    for handle in handles {
        handle.join().unwrap();
    }

    let mut result: Vec<(String, usize)> = frequencies.lock().unwrap().clone().into_iter().collect();
    result.sort_by(|a, b| b.1.cmp(&a.1));
    result
}

