use std::sync::{Arc, Mutex};

fn main() {
    let counter = Arc::new(Mutex::new(0));
    let counter_clone = counter.clone();

    // Forgot to join the thread
    thread::spawn(move || {
        let mut num = counter_clone.lock().unwrap();
        *num += 1;
    });

    println!("Counter: {}", counter.lock().unwrap());  // Might be 0
}

phase2.explanation:
The thread might not finish before the main thread prints.

**The fix:**
```rust
let handle = thread::spawn(move || {
    // ...
});
handle.join().unwrap();  // Wait for thread
```

**Rust-chan says:**
"Always join threads when you need the result."
